const searchQuestionBank = `-- name: SearchQuestionBank :many
SELECT b.archived,v.id, v.bank_id, v.version, v.title, v.prompt, v.type, v.max_score, v.requirements, v.reference_answer, v.reference_state, v.options, v.correct_answer, v.knowledge_point_id, v.evidence_refs, v.state, v.created_by, v.created_at FROM question_bank b
JOIN LATERAL(SELECT id, bank_id, version, title, prompt, type, max_score, requirements, reference_answer, reference_state, options, correct_answer, knowledge_point_id, evidence_refs, state, created_by, created_at FROM bank_question_versions bv WHERE bv.bank_id=b.id ORDER BY version DESC LIMIT 1) v ON true
WHERE b.course_id=$1
AND ($2::text='' OR strpos(lower(v.title||' '||v.prompt),lower($2))>0)
AND ($3::text='' OR CASE WHEN $3='archived' THEN b.archived ELSE NOT b.archived AND v.state=$3 END)
AND ($4::text='' OR v.type=$4)
AND ($5::text='' OR v.knowledge_point_id=$5)
AND ($6::text='' OR EXISTS(SELECT 1 FROM topic_links l WHERE l.bank_version_id=v.id AND l.topic_id=$6))
ORDER BY b.created_at DESC,b.id LIMIT $8 OFFSET $7
`

type SearchQuestionBankParams struct {
	CourseID     string `json:"course_id"`
	Search       string `json:"search"`
	State        string `json:"state"`
	QuestionType string `json:"question_type"`
	PointID      string `json:"point_id"`
	TopicID      string `json:"topic_id"`
	PageOffset   int32  `json:"page_offset"`
	PageLimit    int32  `json:"page_limit"`
}

type SearchQuestionBankRow struct {
	Archived         bool               `json:"archived"`
	ID               string             `json:"id"`
	BankID           string             `json:"bank_id"`
	Version          int32              `json:"version"`
	Title            string             `json:"title"`
	Prompt           string             `json:"prompt"`
	Type             string             `json:"type"`
	MaxScore         int32              `json:"max_score"`
	Requirements     string             `json:"requirements"`
	ReferenceAnswer  string             `json:"reference_answer"`
	ReferenceState   string             `json:"reference_state"`
	Options          []string           `json:"options"`
	CorrectAnswer    string             `json:"correct_answer"`
	KnowledgePointID pgtype.Text        `json:"knowledge_point_id"`
	EvidenceRefs     json.RawMessage    `json:"evidence_refs"`
	State            string             `json:"state"`
	CreatedBy        string             `json:"created_by"`
	CreatedAt        pgtype.Timestamptz `json:"created_at"`
}

func (q *Queries) SearchQuestionBank(ctx context.Context, arg SearchQuestionBankParams) ([]SearchQuestionBankRow, error) {
	rows, err := q.db.Query(ctx, searchQuestionBank,
		arg.CourseID,
		arg.Search,
		arg.State,
		arg.QuestionType,
		arg.PointID,
		arg.TopicID,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchQuestionBankRow{}
	for rows.Next() {
		var i SearchQuestionBankRow
		if err := rows.Scan(
			&i.Archived,
			&i.ID,
			&i.BankID,
			&i.Version,
			&i.Title,
			&i.Prompt,
			&i.Type,
			&i.MaxScore,
			&i.Requirements,
			&i.ReferenceAnswer,
			&i.ReferenceState,
			&i.Options,
			&i.CorrectAnswer,
			&i.KnowledgePointID,
			&i.EvidenceRefs,
			&i.State,
			&i.CreatedBy,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

